const express = require('express');
const cors = require('cors');
const bodyParser = require('body-parser');
const axios = require('axios');

const app = express();
app.use(cors());
app.use(bodyParser.json());

// Ezt a címet cseréld le a saját USDC (Polygon) pénztárca címedre!
const WALLET_ADDRESS = '0xyourwalletaddress';

app.post('/api/pay', async (req, res) => {
  const { amount, description } = req.body;

  try {
    // PayGate.to API hívás (dokumentáció alapján!)
    const response = await axios.post('https://api.paygate.to/create-payment', {
      wallet: WALLET_ADDRESS,
      amount: amount,
      currency: 'USD',
      description: description
    });

    // A válaszban lesz egy payment_url, ezt küldjük vissza
    res.json({ paymentUrl: response.data.payment_url });
  } catch (err) {
    console.error('PayGate API hiba:', err.response?.data || err.message);
    res.status(500).json({ error: 'Fizetési hiba' });
  }
});

